package dev.veltraph.client.chocolate;
import com.google.gson.Gson;
import java.util.*;
/** Separate local receipts per explicit profile scope; malformed data always denies action. */
public record ChocolateFactoryHistory(int schema,Map<String,ChocolateFactoryModule.Journal> profiles,List<Receipt> receipts,Map<String,ChocolateActionJournal> actions,Map<String,ChocolateFactoryModule.Journal> queueIntents,Map<String,ChocolateQueueIntent> queueContracts) {
    public record Receipt(String id,ChocolateFactoryModule.Journal journal) {}
    public ChocolateFactoryHistory {profiles=Map.copyOf(profiles);queueContracts=queueContracts==null?Map.of():Map.copyOf(queueContracts);for(var e:queueContracts.entrySet())if(!e.getKey().equals(e.getValue().id()))throw new IllegalArgumentException("Durable queue contract identity mismatch");queueIntents=queueIntents==null?Map.of():Map.copyOf(queueIntents);for(var entry:queueIntents.entrySet())if(entry.getKey().isBlank()||!entry.getKey().equals(entry.getValue().intentId()))throw new IllegalArgumentException("Queue intent identity mismatch");actions=actions==null?Map.of():Map.copyOf(actions);for(var entry:actions.entrySet())if(!entry.getKey().equals(entry.getValue().id()))throw new IllegalArgumentException("Consequential journal identity mismatch");var unique=new LinkedHashMap<String,Receipt>();if(receipts!=null)for(var receipt:receipts){if(receipt==null||receipt.id()==null||receipt.id().isBlank()||receipt.journal()==null||!"ACKNOWLEDGED".equals(receipt.journal().status()))throw new IllegalArgumentException("Invalid receipt");var previous=unique.putIfAbsent(receipt.id(),receipt);if(previous!=null&&!previous.equals(receipt))throw new IllegalArgumentException("Conflicting Factory receipt identity");}receipts=List.copyOf(unique.values());}
    /** Existing schema-1 histories did not contain the additive receipt list. */
    public ChocolateFactoryHistory(int schema,Map<String,ChocolateFactoryModule.Journal> profiles){this(schema,profiles,List.of(),Map.of(),Map.of(),Map.of());}
    public ChocolateFactoryHistory(int schema,Map<String,ChocolateFactoryModule.Journal> profiles,List<Receipt> receipts){this(schema,profiles,receipts,Map.of(),Map.of(),Map.of());}
    public ChocolateFactoryHistory(int schema,Map<String,ChocolateFactoryModule.Journal> profiles,List<Receipt> receipts,Map<String,ChocolateActionJournal> actions){this(schema,profiles,receipts,actions,Map.of(),Map.of());}
    public ChocolateFactoryHistory(int schema,Map<String,ChocolateFactoryModule.Journal> profiles,List<Receipt> receipts,Map<String,ChocolateActionJournal> actions,Map<String,ChocolateFactoryModule.Journal> queueIntents){this(schema,profiles,receipts,actions,queueIntents,Map.of());}
    public ChocolateFactoryHistory withContract(ChocolateQueueIntent intent){var contracts=new LinkedHashMap<>(queueContracts);var previous=contracts.putIfAbsent(intent.id(),intent);if(previous!=null&&!previous.equals(intent))throw new IllegalArgumentException("Conflicting durable original intent");return new ChocolateFactoryHistory(schema,profiles,receipts,actions,queueIntents,contracts);}
    private static boolean pendingQueue(ChocolateFactoryModule.Journal j){return j==null||j.schema()!=1||j.status()==null||Set.of("PENDING","UNKNOWN","ACKNOWLEDGED_UNPERSISTED").contains(j.status());}
    /** Rollback updates the original intent without overwriting a newer same-scope intent. */
    public String withManualQueueJournal(ChocolateFactoryModule.Journal journal){if(journal.intentId().isBlank())throw new IllegalArgumentException("Retained queue intent ID required");var archive=new LinkedHashMap<>(queueIntents);archive.put(journal.intentId(),journal);var latest=new LinkedHashMap<>(profiles);var current=latest.get(journal.scope());if(current==null||current.intentId().equals(journal.intentId()))latest.put(journal.scope(),journal);return new Gson().toJson(new ChocolateFactoryHistory(schema,latest,receipts,actions,archive,queueContracts));}
    public String withAction(ChocolateActionJournal journal){var next=new LinkedHashMap<>(actions);var existing=next.get(journal.id());if(existing!=null&&(!existing.scope().equals(journal.scope())||!existing.action().equals(journal.action())||!existing.evidence().equals(journal.evidence())))throw new IllegalArgumentException("Conflicting consequential intent identity");next.put(journal.id(),journal);return new Gson().toJson(new ChocolateFactoryHistory(schema,profiles,receipts,next,queueIntents,queueContracts));}
    public static ChocolateFactoryHistory decode(String text){if(text.isBlank())return new ChocolateFactoryHistory(1,Map.of());try{var h=new Gson().fromJson(text,ChocolateFactoryHistory.class);if(h==null||h.schema()!=1||h.profiles()==null||h.receipts().stream().anyMatch(r->r==null||r.id()==null||r.id().isBlank()||r.journal()==null||!"ACKNOWLEDGED".equals(r.journal().status())))throw new IllegalArgumentException();return h;}catch(RuntimeException e){throw new IllegalArgumentException("Local Factory receipt history is unreadable; reconcile explicitly",e);}}
    public boolean pending(){return queueIntents.values().stream().anyMatch(ChocolateFactoryHistory::pendingQueue)||actions.values().stream().anyMatch(ChocolateActionJournal::pending)||profiles.values().stream().anyMatch(ChocolateFactoryHistory::pendingQueue);}
    public String with(ChocolateFactoryModule.Journal journal){return with(journal,"ACKNOWLEDGED".equals(journal.status())?UUID.randomUUID().toString():null);}
    /** Runtime receipt IDs make repeated terminal polling one persisted spend. */
    public String with(ChocolateFactoryModule.Journal journal,String receiptId){
        var entries=new LinkedHashMap<>(profiles);entries.put(journal.scope(),journal);var retained=new ArrayList<>(receipts);
        if("ACKNOWLEDGED".equals(journal.status())){if(receiptId==null||receiptId.isBlank())throw new IllegalArgumentException("Acknowledged spend requires receipt identity");var existing=retained.stream().filter(r->r.id().equals(receiptId)).findFirst();if(existing.isPresent()&&!existing.get().journal().equals(journal))throw new IllegalArgumentException("Conflicting Factory receipt identity");if(existing.isEmpty())retained.add(new Receipt(receiptId,journal));}
        var archive=new LinkedHashMap<>(queueIntents);if(!journal.intentId().isBlank())archive.put(journal.intentId(),journal);return new Gson().toJson(new ChocolateFactoryHistory(1,entries,retained,actions,archive,queueContracts));
    }
}
